const results=[];const check=(name,actual,expected)=>results.push({name,actual,expected,ok:JSON.stringify(actual)===JSON.stringify(expected)});
const supports=(property,value)=>CSS.supports(property,value);
for(const property of Object.keys(styleInputSchema))check("native grammar "+property,isStyleScalar(property,property==="display"?"block":"initial",supports,["block","none"]),true);
for(const [property,value,expected] of [
 ["padding","-1px",false],["margin","-1px",true],["padding",-2,false],["margin",-2,true],
 ["padding","var(--custom-space)",true],["padding",0,true],["padding",.5,true],["padding",13,false],
 ["width",8,true],["width",-8,false],["width","fit-content",true],["width","50%",true],
 ["borderWidth","1px 2px 3px 4px",true],["borderWidth","1px 2px 3px 4px 5px",false],
 ["borderInlineWidth","1px 2px",true],["borderInlineWidth","1px 2px 3px",false],
 ["borderInlineStartWidth","1px 2px",false],["borderInlineStartWidth","1px",true],
 ["borderBlockStyle","solid dashed",true],["borderBlockStartStyle","solid dashed",false],
 ["borderColor","red blue green black",true],["borderInlineColor","red blue green",false],
 ["borderRadius",0,true],["borderRadius",2,false],["borderRadius","2px",true],
 ["gridColumnStart",0,false],["gridColumnStart",-1,true],["zIndex",0,true],
 ["opacity",1.2,false],["opacity","2",true],["aspectRatio",0,false],["aspectRatio","16 / 9",true],
 ["flexGrow",.5,true],["flexGrow",-1,false],["display","contents",false],["display","grid",false]
])check(property+" accepts "+JSON.stringify(value),isStyleScalar(property,value,supports,["block","none"]),expected);
const scalar=property=>value=>isStyleScalar(property,value,supports,["block","none"]);
check("numeric opacity attribute obeys numeric bounds",parseResponsiveAttribute("2",scalar("opacity"),{numbers:true}).diagnostic?.reason,"value");
check("numeric zero reads as a number",parseResponsiveAttribute("0",scalar("padding"),{numbers:true}).value,0);
const grid=value=>typeof value==="string"&&CSS.supports("grid-template-columns",value);
check("bracketed grid scalar precedes JSON",parseResponsiveAttribute("[main] 1fr [end]",grid).value,"[main] 1fr [end]");
check("invalid JSON has no override",parseResponsiveAttribute('{"compact":',scalar("padding"),{numbers:true}).value===undefined,true);
check("unknown condition has no override",parseResponsiveAttribute('{"tiny":2}',scalar("padding"),{numbers:true}).value===undefined,true);
check("equivalent conflict has no override",parseResponsiveAttribute('{"compactOnly":2,"mediumDown":4}',scalar("padding"),{numbers:true}).value===undefined,true);
check("null positions survive HTML conversion",parseResponsiveAttribute("[0,null,4]",scalar("padding"),{numbers:true}).value,[0,null,4]);
const validators={padding:value=>copyResponsiveInput(value,scalar("padding")),backgroundColor:value=>copyResponsiveInput(value,scalar("backgroundColor")),gridTemplateColumns:value=>copyResponsiveInput(value,grid)};
class InputTarget extends HTMLElement{
 static observedAttributes=["padding","background-color","grid-template-columns"];
 inputs=createOrderedStyleInputs(validators);diagnostics=[];
 attributeChangedCallback(name,old,value){const property=name==="background-color"?"backgroundColor":name==="grid-template-columns"?"gridTemplateColumns":name;const guard=property==="gridTemplateColumns"?grid:scalar(property);const parsed=parseResponsiveAttribute(value,guard,{numbers:property==="padding"});this.inputs.set(property,parsed.value);if(parsed.diagnostic)this.diagnostics.push(parsed.diagnostic);}
}
customElements.define("responsive-input-target",InputTarget);
const parent=document.createElement("div");parent.innerHTML='<responsive-input-target padding="2" background-color="red" grid-template-columns="[main] 1fr [end]"></responsive-input-target>';document.body.append(parent);const target=parent.firstElementChild;
check("HTML callback stores a numeric token",target.inputs.get("padding"),2);
check("HTML callback stores bracketed CSS",target.inputs.get("gridTemplateColumns"),"[main] 1fr [end]");
target.setAttribute("padding",'{"compact":');
check("malformed update removes prior override",target.inputs.get("padding")===undefined,true);
check("malformed update preserves unrelated value",target.inputs.get("backgroundColor"),"red");
check("malformed update reports bounded diagnostic",target.diagnostics.at(-1),{code:"invalid-responsive-attribute",reason:"syntax"});
target.setAttribute("padding","4px");
check("literal CSS remains a string",target.inputs.get("padding"),"4px");
target.setAttribute("padding",'{"medium":4,"compact":0}');
check("authored keys survive conversion",Object.keys(target.inputs.get("padding")),["medium","compact"]);
check("structured write does not mutate source attribute",target.getAttribute("padding"),'{"medium":4,"compact":0}');
target.removeAttribute("padding");check("attribute removal clears current value",target.inputs.get("padding")===undefined,true);
parent.remove();
const config=createBreakpointConfiguration();config.read();config.configure({medium:40});const widths=config.use();let rejected=false;try{config.configure({medium:41});}catch{rejected=true;}check("conflicting change after use fails",rejected,true);check("identical repeat is harmless",config.configure({medium:40})===widths,true);
const range=normalizeResponsive({medium:1},value=>typeof value==="number",widths)[0];check("normalization uses configured rem value",range.min,40);
const frame=document.createElement("iframe");frame.style.border="0";document.body.append(frame);const doc=frame.contentDocument;doc.open();doc.write('<!doctype html><style>#target{--active:0}@media(width >= '+range.min+'rem){#target{--active:1}}</style><div id=target></div>');doc.close();
for(const [width,expected] of [[639,"0"],[640,"1"]]){frame.style.width=width+"px";frame.getBoundingClientRect();await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));check("configured viewport width "+width,frame.contentWindow.innerWidth,width);check("configured media boundary "+width,frame.contentWindow.getComputedStyle(doc.querySelector("#target")).getPropertyValue("--active").trim(),expected);}
frame.remove();
const computed=document.createElement("div");computed.style.cssText="--negative:-4px;padding:8px;padding:var(--negative)";document.body.append(computed);check("unresolved variable keeps native computed-value rules",getComputedStyle(computed).paddingTop,"0px");computed.remove();
window.__results={results};

